package io.github.jesterportfolio.hearth.gathering;

import io.github.jesterportfolio.hearth.persistence.*;
import io.github.jesterportfolio.hearth.session.*;
import io.github.jesterportfolio.hearth.lifecycle.*;
import org.bukkit.*;
import org.bukkit.entity.Player;
import org.bukkit.event.*;
import org.bukkit.event.player.PlayerQuitEvent;
import org.bukkit.event.player.PlayerMoveEvent;
import org.bukkit.event.player.PlayerTeleportEvent;
import org.bukkit.plugin.java.JavaPlugin;
import java.util.*;
import java.util.concurrent.*;
import java.util.function.*;

/** 격리 개발 입퇴장 명령과 실제 채집 이벤트 경계. 일반 인던 입장/배치 정책을 확정하지 않습니다. */
public final class PaperGathering implements AutoCloseable,Listener {
    public record Binding(GatheringDungeon dungeon,PaperGatheringArea area){}
    private final JavaPlugin plugin;private final PostgresProgressStore db;private final ServerProgressAccess access;private final PaperSessionAdapter sessions;private final Map<UUID,WorldLifecycle> worlds;private final Executor owner;private final LongSupplier clock;private final Function<UUID,CompletionStage<Void>> saving;public final GatheringContent content;
    private final Map<UUID,Binding> bindings=new HashMap<>();private final Map<UUID,Live> players=new HashMap<>();private final org.bukkit.scheduler.BukkitTask timer;private boolean closed;
    public PaperGathering(JavaPlugin plugin,PostgresProgressStore db,ServerProgressAccess access,PaperSessionAdapter sessions,Map<UUID,WorldLifecycle> worlds,GatheringContent content,Executor owner,LongSupplier clock,Function<UUID,CompletionStage<Void>> saving){if(!plugin.getConfig().getBoolean("gathering-verification-enabled")||!Boolean.getBoolean("hearth.verification.gathering"))throw new IllegalStateException("GATHERING_ISOLATED_GATE");this.plugin=plugin;this.db=db;this.access=access;this.sessions=sessions;this.worlds=worlds;this.content=content;this.owner=owner;this.clock=clock;this.saving=saving;sessions.gathering(this::entry,this::change,this::command);Bukkit.getPluginManager().registerEvents(this,plugin);timer=Bukkit.getScheduler().runTaskTimer(plugin,()->{if(closed||!Boolean.getBoolean("hearth.verification.sessionManual"))return;for(var b:bindings.values())if(b.dungeon().snapshot().phase()==GatheringStore.Phase.OPEN)b.dungeon().pulse().exceptionally(e->{plugin.getLogger().warning("HEARTH_GATHERING_HOLD");return null;});},20,20);}
    private static void main(){if(!Bukkit.isPrimaryThread())throw new IllegalStateException("GATHERING_MAIN_THREAD");}
    public CompletionStage<Binding> bind(ServerProgressAccess.Context ctx,boolean create,PaperGatheringArea.People people){main();var existing=bindings.get(ctx.storyRunId());if(existing!=null)return CompletableFuture.completedFuture(existing);var world=Objects.requireNonNull(worlds.get(ctx.storyRunId()));var store=new PostgresGatheringStore(db,access,ctx,content.id());var template=content.templates().get(content.active());var initial=new GatheringStore.State(ctx.storyRunId(),content.id(),world.mapping().physicalId(),0,0,content.area().hash(),template.version(),template.hash(),GatheringStore.Phase.OPEN,null,true,clock.getAsLong()+content.intervalMillis());
        return (create?store.create(initial):store.read()).thenApplyAsync(state->{if(closed||!state.world().equals(world.mapping().physicalId()))throw new IllegalStateException("GATHERING_WORLD_MISMATCH");if(bindings.containsKey(ctx.storyRunId()))throw new IllegalStateException("GATHERING_BIND_BUSY");try{var area=new PaperGatheringArea(plugin,db,world,content,people,owner,state.generation()==0);var controller=new GatheringDungeon(content,store,state,area,owner,PaperGathering::main,clock);var b=new Binding(controller,area);bindings.put(ctx.storyRunId(),b);return b;}catch(Exception e){throw new CompletionException(e);}},owner);
    }
    private Binding binding(Player p){var s=sessions.prepared(p);return s==null?null:bindings.get(s.context().storyRunId());}
    private boolean inside(org.bukkit.Location l){return content.area().contains(l.getX(),l.getY(),l.getZ());}
    private boolean entry(Player p,Location to){var s=sessions.prepared(p);if(s==null)return false;var w=worlds.get(s.context().storyRunId());if(w==null||!to.getWorld().getUID().equals(w.mapping().physicalId())||!inside(to))return true;var b=binding(p);var live=players.get(p.getUniqueId());return b!=null&&live!=null&&live.session==s&&(b.dungeon().canGather(live,b.dungeon().snapshot().generation())||live.entering&&b.dungeon().reserved(live));}
    private boolean change(Player p,org.bukkit.block.Block block){if(!inside(block.getLocation()))return true;var b=binding(p);var live=players.get(p.getUniqueId());return b!=null&&live!=null&&live.current()&&b.dungeon().canGather(live,b.dungeon().snapshot().generation());}
    private final class Live implements GatheringDungeon.Member {final Player p;final PlayerSessions.Session session;boolean locked,entering;Live(Player p,PlayerSessions.Session session){this.p=p;this.session=session;}public UUID player(){return p.getUniqueId();}public Object session(){return session;}public boolean current(){return !closed&&sessions.prepared(p)==session;}void freeze(boolean value){if(value){if(!locked){sessions.freezeTravel(p,session,true);locked=true;}}else if(locked){sessions.freezeTravel(p,session,false);locked=false;}}
        CompletionStage<Boolean> move(GatheringContent.Position to,BooleanSupplier valid){var w=p.getWorld();return w.getChunkAtAsync(((int)Math.floor(to.x()))>>4,((int)Math.floor(to.z()))>>4).thenComposeAsync(c->{if(!current()||!valid.getAsBoolean())return CompletableFuture.completedFuture(false);int x=(int)Math.floor(to.x()),y=(int)Math.floor(to.y()),z=(int)Math.floor(to.z());var floor=w.getBlockAt(x,y-1,z);var feet=w.getBlockAt(x,y,z);var head=w.getBlockAt(x,y+1,z);if(!io.github.jesterportfolio.hearth.combat.CombatPlayers.safeCells(floor.getType().name(),feet.getType().name(),head.getType().name(),floor.getType().isSolid(),feet.isPassable(),head.isPassable()))return CompletableFuture.completedFuture(false);return sessions.combatMove(p,session,new Location(w,to.x(),to.y(),to.z(),to.yaw(),to.pitch()),()->current()&&valid.getAsBoolean());},owner);}}
    public PaperGatheringArea.People livePeople(UUID run){return new PaperGatheringArea.People(){final Set<Live> frozen=Collections.newSetFromMap(new IdentityHashMap<>());public void notice(String text){players.values().stream().filter(p->p.session.context().storyRunId().equals(run)&&p.current()).forEach(p->p.p.sendMessage(text));}
        public CompletionStage<Void> save(List<GatheringDungeon.Member> members){for(var m:members)if(m instanceof Live l&&l.current()){l.freeze(true);frozen.add(l);}return saving.apply(run);}
        public CompletionStage<Void> evacuate(List<GatheringDungeon.Member> members,BooleanSupplier valid){CompletionStage<Void> work=CompletableFuture.completedFuture(null);for(var m:members)if(m instanceof Live l)work=work.thenComposeAsync(v->{if(!l.current())return CompletableFuture.completedFuture(null);return l.move(content.entrance(),valid).thenAcceptAsync(ok->{if(!Boolean.TRUE.equals(ok))throw new IllegalStateException("GATHERING_EVACUATION_FAILED");players.remove(l.player(),l);},owner);},owner);return work.whenCompleteAsync((v,e)->{frozen.forEach(l->l.freeze(false));frozen.clear();},owner);}
        public void release(){frozen.forEach(l->l.freeze(false));frozen.clear();}
        public CompletionStage<Boolean> enter(GatheringDungeon.Member m,long generation,BooleanSupplier valid){if(!(m instanceof Live l)||!l.current()||!l.session.context().storyRunId().equals(run))return CompletableFuture.completedFuture(false);l.freeze(true);return sessions.saveBoundary(l.p,l.session).thenComposeAsync(v->{l.entering=true;return l.move(content.spawn(),valid);},owner).whenCompleteAsync((v,e)->{l.entering=false;l.freeze(false);},owner);}
    };}
    public List<String> information(Player p){main();var session=Objects.requireNonNull(sessions.current(p),"GATHERING_SESSION_REQUIRED");var b=binding(p);if(b==null)return List.of("채집 구역이 아직 준비되지 않았습니다. 등록 상태를 확인하세요.");var live=players.get(p.getUniqueId());return GatheringStatus.lines(b.dungeon().snapshot(),b.dungeon().occupants(),live!=null&&live.session==session&&live.current()&&b.dungeon().canGather(live,b.dungeon().snapshot().generation()),clock.getAsLong());}
    private boolean command(Player p,String line){if(!line.startsWith("/hearthgather"))return false;var session=sessions.current(p);if(session==null||!sessions.travelEligible(p,session))return true;var b=binding(p);if(b==null){p.sendMessage("채집 fixture가 준비되지 않았습니다.");return true;}if(line.equals("/hearthgather info")){information(p).forEach(p::sendMessage);return true;}if(line.equals("/hearthgather enter")){var live=new Live(p,session);var old=players.putIfAbsent(p.getUniqueId(),live);if(old!=null)live=old;var member=live;b.dungeon().enter(member).whenCompleteAsync((v,e)->{if(e!=null)players.remove(p.getUniqueId(),member);if(member.current())p.sendMessage(e==null?"격리 채집 인던 입장 완료":"채집 입장 거부 또는 보류");},owner);}else if(line.equals("/hearthgather leave")){var live=players.get(p.getUniqueId());if(live!=null){live.freeze(true);sessions.saveBoundary(p,session).thenComposeAsync(v->live.move(content.entrance(),live::current),owner).thenComposeAsync(ok->{if(!Boolean.TRUE.equals(ok))throw new IllegalStateException("GATHERING_EXIT_FAILED");players.remove(p.getUniqueId(),live);return b.dungeon().leave(live);},owner).whenCompleteAsync((v,e)->{live.freeze(false);if(live.current())p.sendMessage(e==null?"채집 인던 퇴장 완료":"퇴장 보류 · 저장 상태 확인 필요");},owner);}}else p.sendMessage("격리 명령: /hearthgather enter, /hearthgather leave, /hearthgather info. 정기 초기화 시 저장 후 입구로 이동합니다.");return true;}
    public void fixture(Player p){var s=Objects.requireNonNull(sessions.current(p));var people=livePeople(s.context().storyRunId());bind(s.context(),false,people).exceptionallyComposeAsync(error->LifecycleFailure.code(error).equals("GATHERING_MISSING")?bind(s.context(),true,people):CompletableFuture.failedFuture(error),owner).whenCompleteAsync((b,e)->plugin.getLogger().info(e==null?"HEARTH_GATHERING_FIXTURE READY":"HEARTH_GATHERING_FIXTURE HOLD"),owner);}
    /** 취소된 이동은 퇴장으로 세지 않습니다. 초기화 이동/중복 콜백도 같은 lease만 정리합니다. */
    private void departed(Player player,Location from,Location to){
        if(to==null||from.getWorld()==null||to.getWorld()==null||!inside(from)||from.getWorld().equals(to.getWorld())&&inside(to))return;
        var member=players.get(player.getUniqueId());if(member==null||member.p!=player)return;
        var world=worlds.get(member.session.context().storyRunId());if(world==null||!from.getWorld().getUID().equals(world.mapping().physicalId()))return;
        if(players.remove(player.getUniqueId(),member)){var b=bindings.get(member.session.context().storyRunId());if(b!=null)b.dungeon().leave(member).exceptionally(error->{plugin.getLogger().warning("HEARTH_GATHERING_EXIT_HOLD");return null;});}
    }
    @EventHandler(priority=EventPriority.MONITOR,ignoreCancelled=true) public void moved(PlayerMoveEvent e){departed(e.getPlayer(),e.getFrom(),e.getTo());}
    @EventHandler(priority=EventPriority.MONITOR,ignoreCancelled=true) public void teleported(PlayerTeleportEvent e){departed(e.getPlayer(),e.getFrom(),e.getTo());}
    @EventHandler(priority=EventPriority.LOWEST) public void quit(PlayerQuitEvent e){var l=players.remove(e.getPlayer().getUniqueId());if(l!=null){var b=bindings.get(l.session.context().storyRunId());if(b!=null)b.dungeon().leave(l);l.freeze(false);}}
    public boolean settled(UUID run){var b=bindings.get(run);return b==null||b.dungeon().settled();}
    public CompletionStage<Void> drain(UUID run){var b=bindings.get(run);return b==null?CompletableFuture.completedFuture(null):b.dungeon().barrier().handle((v,e)->null);}
    public void unloaded(UUID run){var b=bindings.remove(run);if(b!=null){b.dungeon().close();b.area().release();}}
    public void close(){main();if(closed)return;timer.cancel();bindings.values().forEach(b->{b.dungeon().close();b.area().release();});players.values().forEach(l->l.freeze(false));closed=true;HandlerList.unregisterAll(this);sessions.gathering((p,l)->true,(p,b)->true,(p,c)->false);}
}
